{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')


def load_json(name):
    with (ROOT / name).open('r', encoding='utf-8') as f:
        return json.load(f)


def load_csv(name):
    with (ROOT / name).open('r', encoding='utf-8', newline='') as f:
        return list(csv.DictReader(f))


def is_blank(value):
    return value is None or str(value).strip() == ''


def money(value):
    return round(float(value) + 0.0, 2)


def main():
    manifest = load_json('panel_manifest.json')
    shipper_rows = load_csv('shipper_cost.csv')
    contract_rows = load_csv('contract_terms.csv')
    network_rows = load_csv('network_adjustments.csv')
    override_rows = load_csv('lab_capacity_overrides.csv')
    holdouts = load_json('holdouts.json')
    template = load_json('report_template.json')

    excluded_codes = {
        row['panel_code']
        for row in holdouts.get('holdouts', [])
        if row.get('holdout_state') == 'exclude'
    }

    panels = []
    for cluster in manifest.get('service_clusters', []):
        for panel in cluster.get('panels', []):
            if panel.get('analysis_mode') == 'review' and panel.get('panel_code') not in excluded_codes:
                panels.append(panel)

    shipper_lookup = {
        row['shipper_class']: float(row['shipper_cost_usd'])
        for row in shipper_rows
    }
    network_lookup = {
        row['network_tier']: float(row['network_adjustment_per_run_per_lab_usd'])
        for row in network_rows
    }

    # Highest approved, non-blank rev and active_labs override per panel_code.
    override_lookup = {}
    for row in override_rows:
        if row.get('approval') != 'approved':
            continue
        if is_blank(row.get('rev')) or is_blank(row.get('active_labs')):
            continue
        panel_code = row['panel_code']
        rev = int(row['rev'])
        active_labs = int(row['active_labs'])
        current = override_lookup.get(panel_code)
        if current is None or rev > current['rev']:
            override_lookup[panel_code] = {'rev': rev, 'active_labs': active_labs}

    # Latest current contract row keyed by every possible panel_ref.
    contract_by_ref = {}
    for row in contract_rows:
        if row.get('status_flag') != 'current':
            continue
        ref = row.get('panel_ref')
        current = contract_by_ref.get(ref)
        if current is None or row.get('effective_week', '') > current.get('effective_week', ''):
            contract_by_ref[ref] = row

    report_panels = []
    for panel in panels:
        refs = [panel.get('panel_name')] + list(panel.get('alias_labels') or [])
        matched_contracts = [contract_by_ref[ref] for ref in refs if ref in contract_by_ref]
        if not matched_contracts:
            raise ValueError(f"No current contract term found for {panel['panel_code']} using refs {refs!r}")
        contract = max(matched_contracts, key=lambda row: row.get('effective_week', ''))

        base_payment = float(contract['base_payment_per_run_per_lab_usd'])
        network_adjustment = float(network_lookup.get(panel.get('network_tier'), 0.0))
        total_payment = base_payment + network_adjustment
        shipper_cost = float(shipper_lookup[panel['shipper_class']])
        active_labs = override_lookup.get(panel['panel_code'], {}).get(
            'active_labs', int(panel['default_active_labs'])
        )
        reagent_cost_per_1000 = float(panel['reagent_cost_per_1000_tests_usd'])

        def model_metrics(days, runs_per_year, tests_per_lab_per_run):
            annual_revenue = total_payment * active_labs * runs_per_year
            annual_reagent_cost = (
                reagent_cost_per_1000 * active_labs * tests_per_lab_per_run * runs_per_year / 1000.0
            )
            annual_shipper_cost = shipper_cost * runs_per_year
            annual_margin = annual_revenue - annual_reagent_cost - annual_shipper_cost
            return {
                f'runs_per_year_{days}_day': runs_per_year,
                f'tests_per_lab_per_run_{days}_day': int(tests_per_lab_per_run),
                f'annual_revenue_{days}_day_usd': money(annual_revenue),
                f'annual_reagent_cost_{days}_day_usd': money(annual_reagent_cost),
                f'annual_shipper_cost_{days}_day_usd': money(annual_shipper_cost),
                f'annual_margin_{days}_day_usd': money(annual_margin),
            }

        metrics_14 = model_metrics(14, 26, int(panel['tests_per_lab_per_run_14_day']))
        metrics_28 = model_metrics(28, 13, int(panel['tests_per_lab_per_run_28_day']))
        margin_diff = metrics_28['annual_margin_28_day_usd'] - metrics_14['annual_margin_14_day_usd']

        report_panel = {
            'panel_code': panel['panel_code'],
            'panel_name': panel['panel_name'],
            'active_labs': int(active_labs),
            'base_payment_per_run_per_lab_usd': money(base_payment),
            'network_adjustment_per_run_per_lab_usd': money(network_adjustment),
            'total_payment_per_run_per_lab_usd': money(total_payment),
            'shipper_class': panel['shipper_class'],
            'shipper_cost_usd': money(shipper_cost),
            'reagent_cost_per_1000_tests_usd': money(reagent_cost_per_1000),
        }
        report_panel.update(metrics_14)
        report_panel.update(metrics_28)
        report_panel['annual_margin_difference_28_minus_14_usd'] = money(margin_diff)
        report_panels.append(report_panel)

    report_panels.sort(key=lambda row: row['panel_code'])

    total_14 = money(sum(row['annual_margin_14_day_usd'] for row in report_panels))
    total_28 = money(sum(row['annual_margin_28_day_usd'] for row in report_panels))
    total_diff = money(sum(row['annual_margin_difference_28_minus_14_usd'] for row in report_panels))
    abs_diff = money(abs(total_diff))
    threshold = 6000.00
    decision = 'adopt_28_day' if abs_diff < threshold else 'keep_14_day'

    output = {
        'metadata': template['metadata'],
        'audit_notes': template['audit_notes'],
        'analysis': {
            'assumptions': {
                'analysis_mode_filter': 'review',
                'holdout_exclude_state': 'exclude',
                'contract_status_flag': 'current',
                'contract_tie_breaker': 'latest_effective_week',
                'runs_per_year_14_day': 26,
                'runs_per_year_28_day': 13,
                'shipper_cost_formula': 'shipper_cost_usd * runs_per_year',
                'margin_difference_formula': 'annual_margin_28_day_usd - annual_margin_14_day_usd',
                'decision_threshold_usd': money(threshold),
            },
            'panels': report_panels,
            'totals': {
                'total_annual_margin_14_day_usd': total_14,
                'total_annual_margin_28_day_usd': total_28,
                'total_annual_margin_difference_28_minus_14_usd': total_diff,
                'absolute_total_margin_difference_usd': abs_diff,
            },
            'recommendation': {
                'decision': decision,
                'justification': (
                    f"Absolute total margin difference is ${abs_diff:,.2f}, compared with the "
                    f"${threshold:,.2f} threshold; decision is {decision}."
                ),
            },
        },
    }

    with (ROOT / 'diagpanel_policy_report.json').open('w', encoding='utf-8') as f:
        json.dump(output, f, indent=2)
        f.write('\n')

    summary_lines = [
        'Diagnostic panel policy margin summary',
        f"Total 14-day margin (USD): {total_14:.2f}",
        f"Total 28-day margin (USD): {total_28:.2f}",
        f"Absolute difference (USD): {abs_diff:.2f}",
        f"Final decision: {decision}",
    ]
    with (ROOT / 'diagpanel_policy_summary.md').open('w', encoding='utf-8') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
